f = open('data.txt', 'r', encoding='utf-8')
d = {}
for line in f:
    for ch in ',.!?;:':
        line = line.replace(ch, ' ')
    for w in line.lower().split():
        d[w] = d.get(w, 0) + 1
f.close()
items = sorted(d.items(), key=lambda x: (-x[1], x[0]))
for w, c in items[:3]:
    print(w, c)

f = open('data.txt', 'r', encoding='utf-8')
upper = lower = digit = other = 0
for line in f:
    line = line.strip('\n')
    for ch in line:
        if ch.isupper():
            upper += 1
        elif ch.islower():
            lower += 1
        elif ch.isdigit():
            digit += 1
        else:
            other += 1
f.close()
print('大写字母:{}'.format(upper))
print('小写字母:{}'.format(lower))
print('数字:{}'.format(digit))
print('其他字符:{}'.format(other))

f = open('data.txt', 'r', encoding='utf-8')
out = open('out.txt', 'w', encoding='utf-8')
for line in f:
    line = line.rstrip('\n')
    res = ''
    for ch in line:
        if 'a' <= ch <= 'z':
            res += chr((ord(ch) - ord('a') + 3) % 26 + ord('a'))
        elif 'A' <= ch <= 'Z':
            res += chr((ord(ch) - ord('A') + 3) % 26 + ord('A'))
        else:
            res += ch
    print(res)
    out.write(res + '\n')
f.close()
out.close()
